function TrustBar() {
  const isMobile = typeof window !== 'undefined' && window.innerWidth < 768;
  // Reducir la cantidad de logos en el DOM para móviles para mejorar el rendimiento y el tamaño del DOM
  const logosToShow = isMobile ? techLogos.slice(0, 12) : techLogos;
  const doubleLogos = [...logosToShow, ...logosToShow];

  return (
    <section className="bg-white/[0.02] border-y border-white/5 py-6 md:py-8 overflow-hidden relative group">
      <div className="flex overflow-hidden whitespace-nowrap">
        <div className="flex animate-marquee will-change-transform group-hover:pause-marquee">
          {doubleLogos.map((tech, index) => (
            <div
              key={`${tech.name}-${index}`}
              className="flex items-center gap-2 md:gap-3 mx-4 md:mx-8 transition-opacity duration-300 hover:opacity-100 opacity-80"
            >
              <img
                src={tech.svg}
                alt={tech.name}
                className="h-6 w-6 md:h-8 md:w-8 object-contain"
                loading="lazy"
              />
              <span className="text-xs md:text-sm font-medium text-gray-400 tracking-tight">
                {tech.name}
              </span>
            </div>
          ))}
        </div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes marquee {
          0% { transform: translateX(0); }
          100% { transform: translateX(-50%); }
        }
        .animate-marquee {
          display: flex;
          width: max-content;
          animation: marquee 50s linear infinite;
        }
        @media (hover: hover) {
          .group:hover .group-hover\\:pause-marquee {
            animation-play-state: paused;
          }
        }
        @media (max-width: 768px) {
          .animate-marquee {
            animation-duration: 30s;
          }
        }
      `}} />
    </section>
  );
}

export default TrustBar;
